if (-not (Test-Path -LiteralPath $logDir)) { [void](New-Item -ItemType Directory -Path $logDir -Force) }
$logFile = Join-Path $logDir ("$taskId.log")

function Write-Report { param([string]$s) Write-Output $s }

if ([string]$in.name -eq 'list') {
