$vars = @{}
if ($spec.params) { foreach ($p in $spec.params.PSObject.Properties) { if ($null -ne $p.Value) { $vars[$p.Name] = [string]$p.Value } } }
if ($in.params) { foreach ($p in $in.params.PSObject.Properties) { $vars[$p.Name] = [string]$p.Value } }
