        } catch { $why = $_.Exception.Message; $code = -2 }
        $sw.Stop(); $ms = $sw.ElapsedMilliseconds
        $out = ''
        if (Test-Path -LiteralPath $so) { $out = [IO.File]::ReadAllText($so) }
        if (Test-Path -LiteralPath $se) { $e = [IO.File]::ReadAllText($se); if ($e) { $out += "`n" + $e } }
